const PREFIX = 'athanor-' + EDITION + '-';
const CACHE = PREFIX + VERSION;

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    // a few at a time: some hundred files, the card scans among them
    for (let i = 0; i < FILES.length; i += 12) {
      await Promise.all(FILES.slice(i, i + 12).map(async f => {
        const url = new URL(f, self.location).href;
        const r = await fetch(url, { cache: 'reload' });
        if (!r.ok) throw new Error(f + ' ' + r.status);
        await c.put(url, r);
      }));
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('athanor-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    // the pages take their settings in the query (tools/chart.html?open=…): the file is the same
    let hit = await c.match(req.url, { ignoreSearch: true });
    if (!hit && url.pathname.endsWith('/')) hit = await c.match(new URL('index.html', url).href);
    return hit || fetch(req);
  })());
});
